/* Embedded EV charging raw data — gzip + base64. Decoded at runtime via DecompressionStream. */
window.__ELMI_DATA_B64 = "";
window.loadElmiData = async function(){
  const b64 = window.__ELMI_DATA_B64;
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  const txt = await new Response(stream).text();
  const obj = JSON.parse(txt);
  const base = Date.parse(obj.start.replace(' ','T')+':00Z');
  const ST = obj.statuses;
  let last = null;
  const rows = obj.rows.map(r=>{
    const t = base + r[0]*60000;
    const ff = (v,key)=> (v==null && last) ? last[key] : v;
    const o = {
      t,
      ac_kwh:ff(r[1],'ac_kwh'), ac_kw: r[2]==null?0:r[2], bat_soc:ff(r[3],'bat_soc'), bat_kw: r[4]==null?0:r[4],
      g1_kwh:ff(r[5],'g1_kwh'), g1_soc:ff(r[6],'g1_soc'), g1_kw: r[7]==null?0:r[7], g1_st:r[8]<0?null:ST[r[8]],
      g2_kwh:ff(r[9],'g2_kwh'), g2_soc:ff(r[10],'g2_soc'), g2_kw: r[11]==null?0:r[11], g2_st:r[12]<0?null:ST[r[12]],
      gap: r[1]==null
    };
    last = o;
    return o;
  });
  return { sn:obj.sn, start:obj.start, statuses:ST, rows };
};